        public PanelWindow(KittenApp app){
            this.app=app;Title="草鱼的小窝";Width=760;Height=Math.Min(720,SystemParameters.WorkArea.Height-24);MinWidth=660;MinHeight=Math.Min(580,Height);ResizeMode=ResizeMode.CanResize;WindowStartupLocation=WindowStartupLocation.CenterScreen;Resources=GrassFishUi.Create();Background=new SolidColorBrush(Color.FromRgb(248,250,242));FontFamily=new FontFamily("Microsoft YaHei UI");
            Root=(Grid)XamlReader.Parse(Layout);Content=Root;((Image)Root.FindName("Portrait")).Source=app.Art.Portrait;status=TB("Status");notes=TB("Notes");next=TB("NextWater");tabs=(TabControl)Root.FindName("Tabs");
            monitor=C("Monitor");follow=C("Follow");animations=C("Animations");interval=C("Interval");fixedWater=C("FixedWater");meal=C("Meal");startup=C("Startup");minutes=T("Minutes");waterTimes=T("WaterTimes");mealTimes=T("MealTimes");radius=(Slider)Root.FindName("Radius");small=(RadioButton)Root.FindName("SizeSmall");medium=(RadioButton)Root.FindName("SizeMedium");large=(RadioButton)Root.FindName("SizeLarge");small.Style=medium.Style=large.Style=(Style)Resources["SizeChoice"];
            small.Checked+=(s,e)=>SelectSize("small");medium.Checked+=(s,e)=>SelectSize("medium");large.Checked+=(s,e)=>SelectSize("large");B("Save").Click+=(s,e)=>Save();B("Locate").Click+=(s,e)=>app.ShowPet(true);B("Tasks").Click+=(s,e)=>app.OpenTasks();B("HideCat").Click+=(s,e)=>{if(app.Pet.IsVisible)app.HidePet();else app.ShowPet(true);};B("Exit").Click+=(s,e)=>app.Quit();B("TestWater").Click+=(s,e)=>app.Preview("water");B("TestMeal").Click+=(s,e)=>app.Preview("meal");
            interval.Checked+=(s,e)=>minutes.IsEnabled=true;interval.Unchecked+=(s,e)=>minutes.IsEnabled=false;fixedWater.Checked+=(s,e)=>waterTimes.IsEnabled=true;fixedWater.Unchecked+=(s,e)=>waterTimes.IsEnabled=false;meal.Checked+=(s,e)=>mealTimes.IsEnabled=true;meal.Unchecked+=(s,e)=>mealTimes.IsEnabled=false;
            scheduleTitle=T("ScheduleTitle");scheduleMessage=T("ScheduleMessage");scheduleTime=T("ScheduleTime");scheduleMinutes=T("ScheduleMinutes");scheduleMode=(ComboBox)Root.FindName("ScheduleMode");scheduleDate=(DatePicker)Root.FindName("ScheduleDate");scheduleEnabled=C("ScheduleEnabled");scheduleImportant=C("ScheduleImportant");days=(WrapPanel)Root.FindName("Days");scheduleRows=(StackPanel)Root.FindName("ScheduleRows");dayBoxes=Enumerable.Range(0,7).Select(n=>new CheckBox{Content=new[]{"日","一","二","三","四","五","六"}[n],Tag=n,FontSize=10,Margin=new Thickness(0,0,8,0)}).ToArray();foreach(var b in dayBoxes)days.Children.Add(b);scheduleMode.SelectionChanged+=(s,e)=>ModeUi();B("NewSchedule").Click+=(s,e)=>Edit(null);B("CancelSchedule").Click+=(s,e)=>Edit(null);B("SaveSchedule").Click+=(s,e)=>SaveSchedule();
            Reload();Edit(null);
            B("Today").Click+=(s,e)=>app.OpenToday();
        }
        TextBlock TB(string n){return(TextBlock)Root.FindName(n);}CheckBox C(string n){return(CheckBox)Root.FindName(n);}TextBox T(string n){return(TextBox)Root.FindName(n);}Button B(string n){return(Button)Root.FindName(n);}
        public void Reload(){loading=true;var s=app.Config;monitor.IsChecked=s.MonitorCodex;follow.IsChecked=s.FollowMouse;animations.IsChecked=s.Animations;interval.IsChecked=s.WaterIntervalEnabled;fixedWater.IsChecked=s.WaterTimesEnabled;meal.IsChecked=s.MealEnabled;minutes.Text=s.WaterMinutes.ToString();waterTimes.Text=s.WaterTimes;mealTimes.Text=s.MealTimes;radius.Value=s.FollowRadius;small.IsChecked=s.PetSize=="small";medium.IsChecked=s.PetSize=="medium";large.IsChecked=s.PetSize=="large";startup.IsChecked=app.Qa?false:Startup.Enabled(app.Exe);startup.IsEnabled=!app.Qa;minutes.IsEnabled=s.WaterIntervalEnabled;waterTimes.IsEnabled=s.WaterTimesEnabled;mealTimes.IsEnabled=s.MealEnabled;loading=false;if(app.Store.Warning!=null)notes.Text=app.Store.Warning;RefreshStatus();RefreshSchedules();}
        void SelectSize(string preset){if(loading)return;app.Config.PetSize=PetSizing.Normalize(preset);app.Pet.ApplySize();app.Persist();notes.Text="草鱼已切换大小并记住，其他设置仍需保存。";}
        void Save(){try{int amount;if(!int.TryParse(minutes.Text,out amount)||amount<1||amount>1440)throw new FormatException("喝水间隔请填写1～1440分钟。");var water=Store.NormalizeTimes(waterTimes.Text);var meals=Store.NormalizeTimes(mealTimes.Text);if(fixedWater.IsChecked==true&&water.Length==0)throw new FormatException("请至少填一个喝水时间。");if(meal.IsChecked==true&&meals.Length==0)throw new FormatException("请至少填一个吃饭时间。");var s=app.Config;bool reset=s.WaterMinutes!=amount||s.WaterIntervalEnabled!=(interval.IsChecked==true),startupChanged=!app.Qa&&Startup.Enabled(app.Exe)!=(startup.IsChecked==true);s.MonitorCodex=monitor.IsChecked==true;s.FollowMouse=follow.IsChecked==true;s.Animations=animations.IsChecked==true;s.WaterIntervalEnabled=interval.IsChecked==true;s.WaterTimesEnabled=fixedWater.IsChecked==true;s.MealEnabled=meal.IsChecked==true;s.WaterMinutes=amount;s.WaterTimes=water;s.MealTimes=meals;s.FollowRadius=(int)radius.Value;if(reset)app.Scheduler.ResetInterval(DateTime.UtcNow);app.Store.Save(s);if(startupChanged)Startup.Set(startup.IsChecked==true,app.Exe);app.Monitor.Enable(s.MonitorCodex);app.Codex.Enable(s.MonitorCodex);app.Badge.Refresh();notes.Text="保存好啦，草鱼会记住。";RefreshStatus();}catch(Exception e){if(!(e is FormatException)&&!(e is IOException)&&!(e is UnauthorizedAccessException)&&!(e is System.Security.SecurityException))throw;notes.Text=e.Message;}}
        void ModeUi(){int m=scheduleMode.SelectedIndex;scheduleTime.Visibility=m==3?Visibility.Collapsed:Visibility.Visible;scheduleMinutes.Visibility=m==3?Visibility.Visible:Visibility.Collapsed;TB("TimeLabel").Text=m==3?"间隔分钟":"提醒时间";scheduleDate.Visibility=m==2?Visibility.Visible:Visibility.Collapsed;days.Visibility=m==1?Visibility.Visible:Visibility.Collapsed;}
        void Edit(ScheduleRule rule){editing=rule;scheduleTitle.Text=rule==null?"":rule.Title??"";scheduleMessage.Text=rule==null?"":rule.Message??"";scheduleTime.Text=rule==null?"09:00":rule.Time??"09:00";scheduleMinutes.Text=(rule==null?60:rule.Minutes).ToString();scheduleDate.SelectedDate=rule!=null&&rule.DueLocal!=DateTime.MinValue?rule.DueLocal.Date:DateTime.Today;scheduleMode.SelectedIndex=rule==null?0:Array.IndexOf(new[]{"daily","weekly","once","interval"},rule.Mode);scheduleEnabled.IsChecked=rule==null?true:rule.Enabled;scheduleImportant.IsChecked=rule!=null&&rule.AllowDuringQuiet;foreach(var b in dayBoxes)b.IsChecked=rule!=null?(rule.Days??new int[0]).Contains((int)b.Tag):(int)b.Tag>=1&&(int)b.Tag<=5;TB("EditorTitle").Text=rule==null?"新增一个约定":"修改这个约定";ModeUi();}
        void SaveSchedule(){try{
            if(editing==null&&app.Config.CustomSchedules.Count>=100)throw new FormatException("最多100个约定，先收好不用的提醒吧。");int amount=60;if(scheduleMode.SelectedIndex==3&&!int.TryParse(scheduleMinutes.Text,out amount))throw new FormatException("间隔请填写整数分钟。");
            var r=editing==null?new ScheduleRule():editing.Copy();r.Title=scheduleTitle.Text.Trim();r.Message=scheduleMessage.Text.Trim();r.Mode=new[]{"daily","weekly","once","interval"}[Math.Max(0,scheduleMode.SelectedIndex)];r.Time=r.Mode=="interval"?"09:00":Store.NormalizeTimes(scheduleTime.Text);r.Minutes=amount;r.Days=dayBoxes.Where(b=>b.IsChecked==true).Select(b=>(int)b.Tag).ToArray();r.Enabled=scheduleEnabled.IsChecked==true;r.AllowDuringQuiet=scheduleImportant.IsChecked==true;r.Completed=false;
            if(r.Mode=="once"){if(!scheduleDate.SelectedDate.HasValue||Store.ParseTimes(r.Time).Count!=1)throw new FormatException("请选择日期和一个时间。");r.DueLocal=scheduleDate.SelectedDate.Value.Date.Add(Store.ParseTimes(r.Time).Single());if(r.Enabled&&r.DueLocal<=DateTime.Now)throw new FormatException("一次性提醒请选未来的时间。");}
            r.Validate();bool changed=editing==null||editing.Mode!=r.Mode||editing.Time!=r.Time||editing.Minutes!=r.Minutes||editing.DueLocal!=r.DueLocal||!(editing.Days??new int[0]).SequenceEqual(r.Days)||editing.Enabled!=r.Enabled;if(changed){r.NextUtc=DateTime.MinValue;r.LastFiredLocal=DateTime.MinValue;}
            var before=app.Config.CustomSchedules.ToList();if(editing==null)app.Config.CustomSchedules.Add(r);else app.Config.CustomSchedules[app.Config.CustomSchedules.IndexOf(editing)]=r;
            try{app.Store.Save(app.Config);}catch{app.Config.CustomSchedules=before;throw;}foreach(var pending in app.Config.Pending.Where(p=>p.ScheduleId==r.Id))pending.AllowDuringQuiet=r.AllowDuringQuiet;app.LocalRemindersChanged();notes.Text="约定已保存："+r.Title;Edit(null);RefreshSchedules();
        }catch(Exception e){if(!(e is FormatException)&&!(e is IOException)&&!(e is UnauthorizedAccessException))throw;notes.Text=e.Message;}}
        void RefreshSchedules(){scheduleRows.Children.Clear();if(app.Config.CustomSchedules.Count==0){var t=GrassFishUi.Text("还没有约定。先加一件想让草鱼提醒的小事吧。",11);t.Foreground=GrassFishUi.Muted;t.Margin=new Thickness(4,4,4,15);scheduleRows.Children.Add(t);return;}
            foreach(var r in app.Config.CustomSchedules){var grid=new Grid();grid.ColumnDefinitions.Add(new ColumnDefinition());grid.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var stack=new StackPanel();stack.Children.Add(GrassFishUi.Text(r.Title,12,true));var desc=GrassFishUi.Text(r.Description+(r.Enabled?"":" · 已暂停"),10);desc.Foreground=GrassFishUi.Muted;desc.Margin=new Thickness(0,5,0,0);stack.Children.Add(desc);grid.Children.Add(stack);var actions=new WrapPanel{VerticalAlignment=VerticalAlignment.Center};var edit=GrassFishUi.Button("编辑",()=>Edit(r));var pause=GrassFishUi.Button(r.Enabled?"暂停":"启用",()=>{if(r.Completed){notes.Text="已完成的单次提醒，请编辑日期后重新保存。";return;}r.Enabled=!r.Enabled;r.NextUtc=DateTime.MinValue;app.Persist();RefreshSchedules();});var test=GrassFishUi.Button("试试",()=>{app.Scheduler.PreviewSchedule(r);app.Persist();app.ShowPet(false);app.Bubble.Refresh();});var remove=GrassFishUi.Button("×",()=>{if(MessageBox.Show(this,"删除“"+r.Title+"”以及尚未关闭的同名日程提醒？","收好这个约定",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;app.Config.CustomSchedules.Remove(r);app.Config.Pending.RemoveAll(x=>x.ScheduleId==r.Id);app.Persist();app.Bubble.Refresh();if(editing==r)Edit(null);RefreshSchedules();});foreach(var b in new[]{edit,pause,test,remove}){b.Padding=new Thickness(8,6,8,6);b.FontSize=10;b.Margin=new Thickness(4,0,0,0);actions.Children.Add(b);}Grid.SetColumn(actions,1);grid.Children.Add(actions);scheduleRows.Children.Add(GrassFishUi.Card(grid,new Thickness(12)));}
        }
        public void RefreshStatus(){if(status==null)return;var c=app.Codex.Current;int count=app.Badge.ActivityCount;status.Text=c.Connected?(count>0?"草鱼有 "+count+" 条任务通知":"草鱼已连接 Codex，等你开始"):(c.DesktopRunning?"Codex 任务连接恢复中":app.Status.Detail??"草鱼正在等你…");next.Text=app.Scheduler.NextWaterText(DateTime.UtcNow)+(app.Config.Pending.Count>0?" · "+app.Config.Pending.Count+" 张小纸条":"");}
        public void SelectTab(int index){tabs.SelectedIndex=index;}public void CloseForExit(){Close();}
        public void OpenScheduleEditor(string id){var rule=app.Config.CustomSchedules.FirstOrDefault(r=>r.Id==id);SelectTab(1);Edit(rule);if(rule==null){scheduleMode.SelectedIndex=2;var when=DateTime.Now.AddMinutes(30);scheduleDate.SelectedDate=when.Date;scheduleTime.Text=when.ToString("HH:mm");}((ScrollViewer)Root.FindName("ScheduleScroll")).ScrollToEnd();scheduleTitle.Focus();}
        public void PrepareEditorPreview(){Edit(null);scheduleTitle.Text="今天也好好休息";scheduleMessage.Text="忙完就去伸个懒腰，草鱼在这里等你。";scheduleTime.Text="22:30";notes.Text="生活 / 草鱼设置改完点保存；约定日程单独保存。";}
        public void ScrollEditorPreview(){((ScrollViewer)Root.FindName("ScheduleScroll")).ScrollToEnd();}
